#include <vector>
#include <cstddef>
#include <omp.h>

size_t findFirstEven(std::vector<int> const& x) {
    const size_t n = x.size();
    if (n == 0) return n;

    size_t best = n;

#pragma omp parallel
    {
        size_t local_best = n;

#pragma omp for nowait
        for (size_t i = 0; i < n; ++i) {
            if ((x[i] & 1) == 0) {
                local_best = i;
                break; // first even in this thread's contiguous chunk (static schedule default)
            }
        }

#pragma omp critical
        {
            if (local_best < best) best = local_best;
        }
    }

    return best;
}
